package io.github.jesterportfolio.hearth.auraprobe;

import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.lang.management.ManagementFactory;
import org.bukkit.*;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.command.ConsoleCommandSender;
import com.google.gson.*;

/** 별도 검증 JAR. 운영 기능을 등록하지 않고 소유 격리 콘솔에서만 실행됩니다. */
public final class AuraProbePlugin extends JavaPlugin {
 public Path root;public final List<String> checks=new ArrayList<>();private Object aura;private boolean running;private final ExecutorService io=Executors.newSingleThreadExecutor(r->new Thread(r,"hearth-aura-probe-io"));
 public Executor owner(){return task->Bukkit.getScheduler().runTask(this,task);}public Executor io(){return io;}
 @Override public void onEnable(){try{root=Path.of(System.getProperty("hearth.aura.verification.root","")).toRealPath();if(!root.getFileName().toString().startsWith("hearth-native-economy-run.")||!root.getParent().equals(Path.of("/home/server/hearth-tmp").toRealPath())||!Files.readString(root.resolve(".hearth-aura-isolated")).equals("Hearth AuraSkills isolated v1\n")||!Path.of("").toRealPath().equals(root.resolve("server"))||!Bukkit.getOnlineMode()||!Bukkit.hasWhitelist()||!Bukkit.getIp().equals("127.0.0.1")||!Bukkit.getOnlinePlayers().isEmpty())throw new IllegalStateException("AURA_PROBE_GATE");if(Bukkit.getPluginManager().getPlugin("AuraSkills")!=null)aura=Class.forName("io.github.jesterportfolio.hearth.auraprobe.AuraChecks").getConstructor(AuraProbePlugin.class).newInstance(this);Objects.requireNonNull(getCommand("hearthauraprobe")).setExecutor((sender,cmd,label,args)->{if(sender instanceof ConsoleCommandSender&&args.length==1&&!running)run(args[0]);return true;});getLogger().info("HEARTH_AURA_PROBE_READY aura="+(aura!=null));}catch(Exception error){throw new IllegalStateException("AURA_PROBE_BOOT",error);}}
 public void check(boolean ok,String name){if(!ok)throw new IllegalStateException("AURA_CHECK_"+name);checks.add(name);getLogger().info("HEARTH_AURA_CHECK PASS "+name);}
 private void run(String phase){if(!Set.of("baseline","aura","restore").contains(phase))return;running=true;CompletionStage<?> job;try{job=phase.equals("baseline")?CompletableFuture.completedFuture(null):(CompletionStage<?>)aura.getClass().getMethod("run",String.class).invoke(aura,phase);}catch(Exception e){job=CompletableFuture.failedFuture(e);}job.whenCompleteAsync((v,error)->{if(error!=null){getLogger().log(java.util.logging.Level.SEVERE,"HEARTH_AURA_PROBE FAIL "+phase,error);running=false;}else measure(phase);},owner());}
 private void measure(String phase){var intervals=new ArrayList<Double>();var mspt=new ArrayList<Double>();var bean=ManagementFactory.getThreadMXBean();long[] previous={0},cpuStart={0};int[] tick={0};Bukkit.getScheduler().runTaskTimer(this,task->{int n=++tick[0];if(n<100)return;long now=System.nanoTime();if(n==100){previous[0]=now;cpuStart[0]=bean.getCurrentThreadCpuTime();return;}intervals.add((now-previous[0])/1e6);previous[0]=now;mspt.add(Bukkit.getAverageTickTime());if(n>=500){task.cancel();var out=new JsonObject();out.addProperty("phase",phase);out.addProperty("online_players",Bukkit.getOnlinePlayers().size());out.addProperty("java",System.getProperty("java.version"));out.addProperty("paper",Bukkit.getVersion());out.addProperty("server_thread_cpu_ms",(bean.getCurrentThreadCpuTime()-cpuStart[0])/1e6);out.addProperty("heap_used_bytes",Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory());out.addProperty("tick_interval_p50_ms",percentile(intervals,.5));out.addProperty("tick_interval_p95_ms",percentile(intervals,.95));out.addProperty("observed_mspt_p50",percentile(mspt,.5));out.addProperty("observed_mspt_p95",percentile(mspt,.95));out.addProperty("tps_1m",Bukkit.getTPS()[0]);var plugins=new JsonObject();for(String name:List.of("Hearth","WorldGuard","WorldEdit","AuraSkills","BetterHud")){var plugin=Bukkit.getPluginManager().getPlugin(name);plugins.addProperty(name,plugin==null?"ABSENT":plugin.getDescription().getVersion()+":"+plugin.isEnabled());}out.add("plugins",plugins);var items=new JsonArray();checks.forEach(items::add);out.add("checks",items);out.addProperty("actual_player_events",false);try{Files.writeString(root.resolve("aura-"+phase+"-result.json"),new GsonBuilder().setPrettyPrinting().create().toJson(out)+"\n",StandardOpenOption.CREATE_NEW);getLogger().info("HEARTH_AURA_PROBE PASS "+phase);}catch(Exception e){getLogger().log(java.util.logging.Level.SEVERE,"HEARTH_AURA_PROBE FAIL "+phase,e);}running=false;}},1,1);}
 private static double percentile(List<Double> values,double p){var list=new ArrayList<>(values);Collections.sort(list);return list.get(Math.min(list.size()-1,(int)Math.floor(p*list.size())));}
 public void json(String name,JsonObject value){try{Files.writeString(root.resolve(name),new GsonBuilder().setPrettyPrinting().create().toJson(value)+"\n",StandardOpenOption.CREATE_NEW);}catch(Exception e){throw new CompletionException(e);}}
 @Override public void onDisable(){io.shutdown();try{if(!io.awaitTermination(3,TimeUnit.SECONDS))io.shutdownNow();}catch(InterruptedException e){Thread.currentThread().interrupt();}}
}
